use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl MemEncoder { pub fn new () -> MemEncoder { MemEncoder { data : vec ! [] } } # [inline] pub fn position (& self) -> usize { self . data . len () } pub fn finish (self) -> Vec < u8 > { self . data } # [doc = " Write up to `N` bytes to this encoder."] # [doc = ""] # [doc = " This function can be used to avoid the overhead of calling memcpy for writes that"] # [doc = " have runtime-variable length, but are small and have a small fixed upper bound."] # [doc = ""] # [doc = " This can be used to do in-place encoding as is done for leb128 (without this function"] # [doc = " we would need to write to a temporary buffer then memcpy into the encoder), and it can"] # [doc = " also be used to implement the varint scheme we use for rmeta and dep graph encoding,"] # [doc = " where we only want to encode the first few bytes of an integer. Note that common"] # [doc = " architectures support fixed-size writes up to 8 bytes with one instruction, so while this"] # [doc = " does in some sense do wasted work, we come out ahead."] # [inline] pub fn write_with < const N : usize > (& mut self , visitor : impl FnOnce (& mut [u8 ; N]) -> usize) { self . data . reserve (N) ; let old_len = self . data . len () ; let buf = unsafe { let buf = self . data . as_mut_ptr () . add (old_len) as * mut [u8 ; N] ; * buf = [0 ; N] ; & mut * buf } ; let written = visitor (buf) ; if written > N { Self :: panic_invalid_write :: < N > (written) ; } unsafe { self . data . set_len (old_len + written) } ; } # [cold] # [inline (never)] fn panic_invalid_write < const N : usize > (written : usize) { panic ! ("MemEncoder::write_with::<{N}> cannot be used to write {written} bytes") ; } # [doc = " Helper for calls where [`MemEncoder::write_with`] always writes the whole array."] # [inline] pub fn write_array < const N : usize > (& mut self , buf : [u8 ; N]) { self . write_with (| dest | { * dest = buf ; N }) } }